const msg = $json.message;
if (!msg || !msg.text) return [];
return [{ json: {
  chatId: String(msg.chat.id),
  text: msg.text.trim(),
  firstName: (msg.from?.first_name || 'دوست').replace(/'/g, ''),
  username: msg.from?.username || null,
  sessionId: String(msg.chat.id)
}}];

const user = $('Get Or Create User').item.json;
const stage = user.stage || 'greeting';
const firstName = $('Extract Input').item.json.firstName;
const painPoints = user.pain_points || '';
const objCount = user.objection_count || 0;

const IDENTITY = `تو «سارا» هستی، یک مشاور زناشویی باتجربه و صمیمی.
هرگز مثل ربات یا کاتالوگ حرف نزن. مثل یک دوست قابل اعتماد باش.
همیشه به فارسی پاسخ بده. پیام‌هایت کوتاه باشند (حداکثر 3 جمله).
هیچوقت نگو «به عنوان هوش مصنوعی» یا «به عنوان ربات».
هر پیام رو با یک سوال تموم کن.`;

const PRODUCT = `اطلاعات دوره:
نام: «زندگی مشترک طلایی»
محتوا: ۴۸ ویدیو + ۱۲ کارگاه عملی + پشتیبانی ۳۰ روزه
ضمانت برگشت وجه ۱۴ روزه
۸۷٪ شرکت‌کنندگان بهبود رابطه گزارش دادند`;

const STAGES = {
  greeting: `مرحله: خوش‌آمدگویی\nهدف: ارتباط بساز و بفهم چرا اومدن\nبا اسم ${firstName} سلام کن، یه سوال گرم بپرس\nهنوز از دوره یا قیمت حرف نزن`,
  discovery: `مرحله: کشف مشکل\nهدف: بفهم دقیقاً چه دردی دارن\nسوالات همدلانه بپرس، قضاوت نکن\nدنبال: رابطه سرد، اختلاف، صمیمیت کم، روزمرگی`,
  solution: `مرحله: معرفی راه‌حل\nمشکلات کشف‌شده: ${painPoints}\nاول مشکل رو بازگو کن (تا بدونن شنیده شدن)\nبعد دوره رو به عنوان راه‌حل معرفی کن، نه کاتالوگ`,
  objection: `مرحله: رسیدگی به اعتراض (تعداد قبلی: ${objCount})\nگران است: پرداخت اقساطی رو پیشنهاد بده\nباید فکر کنم: «طبیعیه، اکثر افراد اول همینو می‌گن...»\nوقت ندارم: «۱۵ دقیقه در روز کافیه»\nاگر ${objCount} >= 2 تخفیف ۱۵٪ بده`,
  closing: `مرحله: بستن فروش\nلینک پرداخت رو بفرست\nبگو این هفته ظرفیت محدوده\nبعد از لینک بپرس: «دیدی؟ سوالی داری؟»`
};

const systemPrompt = IDENTITY + '\n\n' + PRODUCT + '\n\n' + (STAGES[stage] || STAGES.greeting);

return [{ json: {
  chatId: $('Extract Input').item.json.chatId,
  text: $('Extract Input').item.json.text,
  sessionId: $('Extract Input').item.json.sessionId,
  firstName,
  systemPrompt,
  currentStage: stage,
  painPoints,
  objCount
}}];

const aiResponse = $json.output;
const stage = $('Build System Prompt').item.json.currentStage;
const userText = $('Extract Input').item.json.text.toLowerCase();
const chatId = $('Extract Input').item.json.chatId;
const objCount = $('Build System Prompt').item.json.objCount;

let nextStage = stage;
let newObjCount = objCount;
let painPoints = $('Build System Prompt').item.json.painPoints;

const has = (words) => words.some(w => userText.includes(w));

const discoveryWords = ['مشکل','همسر','رابطه','اختلاف','خسته','نگران','دعوا','سرد','کمک','زندگی'];
const solutionWords = ['چطور','راه','کمک می','بیشتر','جالب','چی کار','ممنون'];
const closingWords = ['چقدر','قیمت','هزینه','ثبت','بخرم','می‌خوام','خرید'];
const purchasedWords = ['پرداخت کردم','خریدم','ثبت نام کردم','انجام دادم'];
const objectionWords = ['گرون','نمیتونم','بعداً','فکر کنم','همسرم','وقت ندارم','مطمئن نیستم'];

if (stage === 'greeting' && has(discoveryWords)) nextStage = 'discovery';
else if (stage === 'discovery' && has(solutionWords)) nextStage = 'solution';
else if (stage === 'solution' && has(closingWords)) nextStage = 'objection';
else if (stage === 'objection' && has(closingWords)) nextStage = 'closing';
else if (has(purchasedWords)) nextStage = 'purchased';

if (has(objectionWords)) newObjCount += 1;

if (stage === 'discovery' && has(['سرد','دعوا','اختلاف','صمیمیت','نزدیکی','جدایی'])) {
  const pains = [];
  if (userText.includes('سرد')) pains.push('رابطه سرد');
  if (userText.includes('دعوا') || userText.includes('اختلاف')) pains.push('اختلاف نظر');
  if (userText.includes('صمیمیت') || userText.includes('نزدیکی')) pains.push('کمبود صمیمیت');
  if (pains.length) painPoints = JSON.stringify(pains);
}

return [{ json: {
  chatId,
  aiResponse,
  nextStage,
  stageChanged: nextStage !== stage,
  isPurchased: nextStage === 'purchased',
  isClosing: nextStage === 'closing',
  painPoints,
  newObjCount
}}];

